      if (!state.reduced) loadingLoop = gs.timeline({ repeat: -1 }).to('.window-shade', { yPercent: -102, duration: 1.1, ease: 'sine.inOut' }).to({}, { duration: 1.5 }).to('.window-shade', { yPercent: 0, duration: 1.1, ease: 'sine.inOut' }).to({}, { duration: 1.5 });
