    const critical = [...new Set([...sceneAssets('cover'), ...Array.from({length:10},(_,i)=>'loader-digit-'+i)])];
    const weights = window.ASSET_BYTES || {};
    const total = critical.reduce((sum, name) => sum + (weights[name] || 1), 0);
    let done = 0; const progress = { value: 0 };
